    agent_id: int,
    my_history: list[dict],
    observations: list[dict],
    round_num: int,
    recipient_id: int,
    population_size: int
) -> bool:
    """
    Tit-for-Two-Tats variant: cooperate unless the partner has defected
    in their last two interactions where they were the donor.
    """
    # Collect partner's actions in reverse chronological order
    partner_defections = []
    for entry in reversed(my_history):
        if entry["partner"] == recipient_id:
            # Only consider rounds where partner was donor (we were recipient)
            if entry["role"] == "recipient":
                action = entry["partner_action"]
                partner_defections.append(action == "not_donate")
                # Only need last two
                if len(partner_defections) >= 2:
                    break

    # If the last two partner actions were both defections, defect
    if len(partner_defections) >= 2:
        if partner_defections[0] and partner_defections[1]:
            return False  # not donate
        else:
            return True   # donate
    else:
        # First encounter or fewer than 2 interactions: cooperate
        return True

