def strategy(
    agent_id: int,
    my_history: list[dict],
    observations: list[dict],
    round_num: int,
    recipient_id: int,
    population_size: int
) -> bool:
    # Tit-for-tat: start by donating, then copy partner's last action when partner was donor
    # If we were recipient in our last interaction with this partner, use their action
    last_action = None
    for entry in reversed(my_history):
        if entry["partner"] == recipient_id:
            if entry["role"] == "recipient":
                last_action = entry["partner_action"]
            else:
                last_action = entry["action"]  # what we did to them last time
            break
    if last_action is None:
        return True  # first encounter: cooperate
    return last_action == "donate"

import random

def strategy(
    agent_id: int,
    my_history: list[dict],
    observations: list[dict],
    round_num: int,
    recipient_id: int,
    population_size: int
) -> bool:
    # Collect all past interactions with this specific recipient when we were the recipient
    partner_defections = 0
    total_interactions = 0
    last_partner_action = None

    for entry in reversed(my_history):
        if entry["role"] == "recipient" and entry["partner"] == recipient_id:
            total_interactions += 1
            if entry["partner_action"] != "donate":
                partner_defections += 1
            if last_partner_action is None:
                last_partner_action = entry["partner_action"]

    if total_interactions == 0:
        # No history: default to cooperate
        return True

    # If the partner never defected, always cooperate
    if partner_defections == 0:
        return True

    # Determine forgiveness based on overall defection rate
    defection_rate = partner_defections / total_interactions

    if last_partner_action != "donate":
        # Partner defected last time
        if defection_rate > 0.5:
            # High defection rate -> punish more harshly (defect with high probability)
            return random.random() < 0.05  # only 5% cooperation
        else:
            # Low defection rate -> more forgiving
            return random.random() < 0.35  # 35% cooperation
    else:
        # Last action was cooperate, so cooperate normally
        return True
